-- QDNC test candidate. Registration changes the shared NC BP rule table.
-- First stop affected operations and the NC service processes that cache these rules,
-- back up their configuration, disable autocommit, and run the SELECTs below.
-- :confirm_qdnc_test must be 'QDNC_TEST_ONLY' after the operator independently
-- confirms the test environment. :nc_generated_rule_pks must contain 18 distinct,
-- comma-separated 20-character IDs generated by the site's NC primary-key service,
-- in the order of the add_rule calls below. This script does not invent NC IDs.
-- It does not enable mappings or policies and does not COMMIT.

-- The local NC loader does not filter DR in this query. Review every row, including
-- logically deleted rows, before registering or rolling back rule definitions.
SELECT pk_pluginitem,dr,vmodulename,vcomponentname,vextendpointname,veventtype,
       vextendtype,vruleclass,vtargetclass,vextendmodule,iorder,localtype,industrytype
  FROM pub_pluginitem
 WHERE vmodulename='IC' AND UPPER(vcomponentname)='M4455'
 ORDER BY vextendpointname,veventtype,iorder,pk_pluginitem;

SELECT pk_group,pk_org,node_code,button_code,enabled,validated
  FROM qd_es_policy WHERE node_code='40080801'
 ORDER BY pk_group,pk_org,button_code;

SELECT business_state,COUNT(*) request_count FROM qd_es_request
 WHERE node_code='40080801' AND business_state IN ('PENDING','READY','RUNNING')
 GROUP BY business_state;

DECLARE
  v_count NUMBER;
  v_confirm CONSTANT VARCHAR2(40) := :confirm_qdnc_test;
  v_keys CONSTANT VARCHAR2(1000) := :nc_generated_rule_pks;
  TYPE seen_type IS TABLE OF PLS_INTEGER INDEX BY VARCHAR2(20);
  v_seen seen_type;

  PROCEDURE add_rule(p_index PLS_INTEGER,p_point VARCHAR2,p_phase VARCHAR2,p_rule VARCHAR2) IS
    v_pk VARCHAR2(20);
    v_type VARCHAR2(20);
  BEGIN
    v_pk:=REGEXP_SUBSTR(v_keys,'[^,]+',1,p_index);
    IF v_pk IS NULL OR LENGTHB(v_pk)<>20 OR v_seen.EXISTS(v_pk) THEN
      RAISE_APPLICATION_ERROR(-20311,'Invalid or duplicated NC rule key at position '||p_index);
    END IF;
    v_seen(v_pk):=1;
    SELECT COUNT(*) INTO v_count FROM pub_pluginitem WHERE pk_pluginitem=v_pk;
    IF v_count<>0 THEN
      RAISE_APPLICATION_ERROR(-20312,'NC rule key already exists at position '||p_index);
    END IF;
    v_type:=CASE p_phase WHEN 'before' THEN 'addBefore' WHEN 'after' THEN 'addAfter' ELSE NULL END;
    IF v_type IS NULL THEN RAISE_APPLICATION_ERROR(-20313,'Invalid BP rule phase'); END IF;
    INSERT INTO pub_pluginitem
      (pk_pluginitem,dr,vmodulename,vcomponentname,vextendpointname,veventtype,
       vextendtype,vruleclass,vtargetclass,vextendmodule,iorder,localtype,industrytype,vdescription)
    VALUES
      (v_pk,0,'IC','m4455','nc.bs.ic.m4455.maintain.'||p_point,p_phase,
       v_type,'nc.impl.ic.qd.esign.SapplyBpRules$'||p_rule,NULL,'ic',1,'~','~','QD_ESIGN_SAPPLY_PILOT');
  END;
BEGIN
  SAVEPOINT qd_sapply_bp_rules;
  IF SYS_CONTEXT('USERENV','CURRENT_SCHEMA')<>'QDNC'
     OR v_confirm IS NULL OR v_confirm<>'QDNC_TEST_ONLY' THEN
    RAISE_APPLICATION_ERROR(-20314,'Confirm the QDNC test environment before registering BP rules');
  END IF;
  IF v_keys IS NULL OR NOT REGEXP_LIKE(v_keys,'^[A-Za-z0-9_-]{20}(,[A-Za-z0-9_-]{20}){17}$') THEN
    RAISE_APPLICATION_ERROR(-20315,'Supply exactly 18 NC-generated 20-character rule keys');
  END IF;

  -- These locks affect shared tables; run only during the agreed maintenance window.
  LOCK TABLE qd_es_request IN SHARE ROW EXCLUSIVE MODE NOWAIT;
  LOCK TABLE qd_es_node IN SHARE ROW EXCLUSIVE MODE NOWAIT;
  LOCK TABLE qd_es_policy IN SHARE ROW EXCLUSIVE MODE NOWAIT;
  LOCK TABLE pub_pluginitem IN SHARE ROW EXCLUSIVE MODE NOWAIT;

  SELECT COUNT(*) INTO v_count FROM qd_es_policy WHERE node_code='40080801' AND enabled='Y';
  IF v_count<>0 THEN RAISE_APPLICATION_ERROR(-20316,'Disable all outbound-request policies first'); END IF;
  SELECT COUNT(*) INTO v_count FROM qd_es_request
   WHERE node_code='40080801' AND business_state IN ('PENDING','READY','RUNNING');
  IF v_count<>0 THEN RAISE_APPLICATION_ERROR(-20317,'Reconcile unfinished outbound-request requests first'); END IF;
  SELECT COUNT(*) INTO v_count FROM pub_pluginitem
   WHERE vmodulename='IC' AND UPPER(vcomponentname)='M4455';
  IF v_count<>0 THEN
    RAISE_APPLICATION_ERROR(-20318,'Existing m4455 rules require a separate ordering review');
  END IF;

  add_rule(1,'InsertBP','before','BeforeInsert');
  add_rule(2,'InsertBP','after','AfterInsert');
  add_rule(3,'UpdateBP','before','BeforeUpdate');
  add_rule(4,'UpdateBP','after','AfterUpdate');
  add_rule(5,'DeleteBP','before','BeforeDelete');
  add_rule(6,'DeleteBP','after','AfterDelete');
  add_rule(7,'CommitBP','before','BeforeCommit');
  add_rule(8,'CommitBP','after','AfterCommit');
  add_rule(9,'UnCommitBP','before','BeforeUnCommit');
  add_rule(10,'UnCommitBP','after','AfterUnCommit');
  add_rule(11,'ApproveBP','before','BeforeApprove');
  add_rule(12,'ApproveBP','after','AfterApprove');
  add_rule(13,'UnapproveBP','before','BeforeUnApprove');
  add_rule(14,'UnapproveBP','after','AfterUnApprove');
  add_rule(15,'RowCloseBP','before','BeforeRowClose');
  add_rule(16,'RowCloseBP','after','AfterRowClose');
  add_rule(17,'RowOpenBP','before','BeforeRowOpen');
  add_rule(18,'RowOpenBP','after','AfterRowOpen');
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK TO qd_sapply_bp_rules;
    RAISE;
END;
/

-- Re-run the first SELECT and the separate sapply-rule-preflight.sql; compare all
-- 18 rows and keys to the backed-up registration evidence before COMMIT or ROLLBACK.
-- Registering rows does not prove that NC loaded the classes or uses the right CMT.
